const env = typeof $env !== 'undefined' ? $env : process.env;
const endpoint = String(env.TENDER_PRODUCT_MATCHING_URL || 'http://tender-api:8000/product-matching/from-documents').trim();
const apiKey = String(env.TENDER_PYTHON_API_KEY || '').trim();
const form = new FormData();

let tenderName = '';
const allItems = $input.all();
for (const item of allItems) {
  tenderName ||= String(item.json?.tenderName || '').trim();
}
form.append('tender_name', tenderName || 'documents');

let fileCount = 0;
for (let itemIndex = 0; itemIndex < allItems.length; itemIndex++) {
  const item = allItems[itemIndex];
  const binaries = item.binary || {};
  for (const [propertyName, binary] of Object.entries(binaries)) {
    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, propertyName);
    const fileName = String(binary.fileName || propertyName || `document_${fileCount + 1}`);
    const mimeType = String(binary.mimeType || 'application/octet-stream');
    form.append('files', new Blob([buffer], { type: mimeType }), fileName);
    fileCount++;
  }
}

if (!fileCount) {
  throw new Error('No uploaded tender documents found.');
}

const headers = {};
if (apiKey) headers['X-API-Key'] = apiKey;

const response = await fetch(endpoint, { method: 'POST', headers, body: form });
const debugHeader = response.headers.get('x-product-matching-debug-b64') || '';
if (!response.ok) {
  const text = await response.text();
  throw new Error(`Tender Worker returned HTTP ${response.status}: ${text.slice(0, 2000)}`);
}

const arrayBuffer = await response.arrayBuffer();
const outputName = `autopodbor_${(tenderName || 'documents').replace(/[^a-z0-9_-]+/gi, '_').slice(0, 80) || 'documents'}.xlsx`;
const binary = await this.helpers.prepareBinaryData(
  Buffer.from(arrayBuffer),
  outputName,
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
);

let debug = null;
try {
  const normalizedDebug = debugHeader.replace(/-/g, '+').replace(/_/g, '/');
  debug = debugHeader ? JSON.parse(Buffer.from(normalizedDebug, 'base64').toString('utf8')) : null;
} catch {
  debug = debugHeader ? { encoded: debugHeader } : null;
}

return [{
  json: {
    status: 'completed',
    tenderName: tenderName || null,
    uploadedFiles: fileCount,
    fileName: outputName,
    debug,
  },
  binary: { data: binary },
}];
